import json, numpy as np
from scipy.optimize import minimize
from scipy.spatial.distance import pdist
j=json.load(open('indices.json')); el=j['elements'];n=len(el)
x=np.loadtxt('initial.xyz',skiprows=2,usecols=(1,2,3))
bonds=[(a,b) for a,b,_ in j['ligand_bonds']]
cpbonds=[]
for z,r in zip(j['Zn'],j['rings']):
 bonds.append((j['Si'],z))
 for i,a in enumerate(r):
  bonds.append((z,a))
  cpbonds.append((a,r[(i+1)%5]));
  m=r[-1]+1+4*i
  cpbonds.append((a,m))
  cpbonds.extend((m,h) for h in range(m+1,m+4))
bonds+=cpbonds
neighbors=[set() for i in range(n)]
for a,b in bonds:neighbors[a].add(b);neighbors[b].add(a)
bset=set(tuple(sorted((a,b))) for a,b in bonds)
springs={}
for a,b in bset:springs[a,b]=(np.linalg.norm(x[a]-x[b]),150.)
for c in range(n):
 for a in neighbors[c]:
  for b in neighbors[c]:
   if a>=b or (a,b) in springs:continue
   k=18.
   if c in j['Zn'] and (a==j['Si'] or b==j['Si']):k=0.7
   springs[a,b]=(np.linalg.norm(x[a]-x[b]),k)
# Preserve conjugated substructures through 1-4 distances across double/aromatic bonds.
for a,b,order in j['ligand_bonds']:
 if order<1.4:continue
 for p in neighbors[a]-{b}:
  for q in neighbors[b]-{a}:
   t=tuple(sorted([p,q]));
   if t not in springs:springs[t]=(np.linalg.norm(x[p]-x[q]),10.)
sidx=np.array(list(springs));r0=np.array([springs[t][0] for t in springs]);k=np.array([springs[t][1] for t in springs])
nonidx=np.array([(a,b) for a in range(n) for b in range(a+1,n) if (a,b) not in springs])
vdw={'H':1.15,'C':1.7,'N':1.55,'Zn':1.4,'Si':2.0}
rmin=np.array([.83*(vdw[el[a]]+vdw[el[b]]) for a,b in nonidx])

def fg(flat):
 p=flat.reshape(-1,3);g=np.zeros_like(p)
 ds=p[sidx[:,0]]-p[sidx[:,1]];ls=np.linalg.norm(ds,axis=1);d=ls-r0
 en=(k*d*d).sum()
 gg=(2*k*d/ls)[:,None]*ds
 np.add.at(g,sidx[:,0],gg);np.add.at(g,sidx[:,1],-gg)
 ds=p[nonidx[:,0]]-p[nonidx[:,1]];ls=np.linalg.norm(ds,axis=1);d=np.minimum(0,ls-rmin)
 en+=3.*(d*d).sum()
 gg=(6*d/ls)[:,None]*ds
 np.add.at(g,nonidx[:,0],gg);np.add.at(g,nonidx[:,1],-gg)
 return en,g.reshape(-1)
res=minimize(fg,x.flatten(),jac=True,method='L-BFGS-B',options={'maxiter':2500,'gtol':.005,'ftol':1e-8})
print(res.success,res.message,res.fun)
p=res.x.reshape(-1,3)
with open('preopt.xyz','w') as f:
 f.write(f'{n}\nPre-relaxed Si(ZnCp*)2 complex\n')
 for e,pp in zip(el,p):f.write(f'{e} {pp[0]:.8f} {pp[1]:.8f} {pp[2]:.8f}\n')
print('Si bonds',[(a,float(np.linalg.norm(p[a]-p[0]))) for a in neighbors[0]])
